      acc = acc + dir * (q * q * params.pressureScale * other.posMass.w);
      acc = acc + (other.velTemp.xyz - vel) * (q * params.viscosity);
      heatRate = heatRate + (other.velTemp.w - temp) * q * params.thermalDiffusion;
